+.grid{display:grid;gap:var(--gap)}
+.grid.two{grid-template-columns:1.2fr .8fr}
+.grid.three{grid-template-columns:repeat(3, 1fr)}
+.grid.cards{grid-template-columns:repeat(3, 1fr)}
+
+.card{
+  background: linear-gradient(180deg, rgba(18,32,51,.92), rgba(12,24,38,.92));
+  border:1px solid rgba(255,255,255,.10);
+  border-radius:var(--radius);
+  box-shadow: var(--shadow2);
+  padding:18px;
+}
+.card.soft{background: rgba(18,32,51,.65);box-shadow:none}
+.card h3{margin:4px 0 8px;font-size:16px}
+.card p{margin:0;color:var(--muted);font-size:14px}
+.icon{
+  width:40px;height:40px;border-radius:12px;
+  display:grid;place-items:center;
+  background: rgba(0,180,216,.10);
+  border:1px solid rgba(0,180,216,.25);
+}
+.icon svg{width:18px;height:18px}
+
+/* Hero */
+.hero{
+  padding:74px 0 44px;
+}
+.hero h1{font-size:44px;letter-spacing:.2px;line-height:1.08;margin:10px 0 12px}
+.hero .subtitle{color:var(--muted);font-size:17px;max-width:720px}
+.hero .actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}
+.hero .meta{
+  display:flex;gap:14px;flex-wrap:wrap;
+  margin-top:22px;color:var(--muted);font-size:13px
+}
+.pill{display:inline-flex;align-items:center;gap:8px;padding:8px 10px;border-radius:999px;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.10)}
+.pill .dot{width:7px;height:7px;border-radius:99px;background:var(--good);box-shadow:0 0 0 3px rgba(108,194,74,.14)}
