+.banner .tag{color:var(--muted);font-size:13px;margin-top:2px}
+
+/* Tabs */
+.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
+.tab{
+  border:1px solid rgba(255,255,255,.12);
+  background: rgba(255,255,255,.03);
+  color:var(--muted);
+  padding:9px 12px;border-radius:999px;
+  cursor:pointer;
+  transition: background .15s ease, border-color .15s ease, color .15s ease, transform .15s ease;
+}
+.tab:hover{transform: translateY(-1px);border-color:rgba(255,255,255,.18);color:var(--text)}
+.tab[aria-selected="true"]{
+  background: rgba(0,180,216,.14);
+  border-color: rgba(0,180,216,.35);
+  color: var(--text);
+}
+.tabpanel{margin-top:14px}
+
+/* Use cases */
+.use-case-card{cursor:pointer;position:relative;overflow:hidden}
+.use-case-card:before{
+  content:"";position:absolute;inset:-40px;
+  background: radial-gradient(320px 220px at 20% 0%, rgba(0,180,216,.10), transparent 62%),
+              radial-gradient(280px 220px at 90% 20%, rgba(108,194,74,.10), transparent 60%);
+  opacity:.9;
+}
+.use-case-card > *{position:relative}
+.use-case-card:hover{border-color: rgba(0,180,216,.22)}
+
+/* Diagrams */
+.diagram{
+  border:1px solid rgba(255,255,255,.10);
+  background: rgba(10,20,32,.55);
+  border-radius:var(--radius);
+  padding:18px;
+  overflow:hidden;
+}
+.diagram .hint{color:var(--muted);font-size:13px;margin-top:10px}
+.diagram svg{width:100%;height:auto;display:block}
+
+/* Stats rings */
+.stats{display:grid;grid-template-columns:repeat(3, 1fr);gap:16px;margin-top:18px}
+.stat{
+  padding:18px;border-radius:var(--radius);
+  background: rgba(18,32,51,.55);
+  border:1px solid rgba(255,255,255,.10);
+  display:flex;align-items:center;gap:14px;
+}
+.ring{width:64px;height:64px;flex:0 0 auto}
+.stat .value{font-size:22px;font-weight:800;letter-spacing:.2px}
+.stat .label{color:var(--muted);font-size:13px;margin-top:2px}
+
+/* Timeline */
+.timeline{display:grid;gap:12px;margin-top:18px}
+.timeline-item{padding:16px;border-radius:var(--radius2);border:1px solid rgba(255,255,255,.10);background:rgba(18,32,51,.50)}
+.timeline-top{display:flex;align-items:baseline;justify-content:space-between;gap:10px}
+.timeline-top strong{letter-spacing:.2px}
+.timeline-top span{color:var(--muted);font-size:13px}
+.bar{height:10px;border-radius:999px;background: rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.09);overflow:hidden;margin-top:12px}
