+.accordion{display:grid;gap:10px;margin-top:18px}
+.acc{
+  border:1px solid rgba(255,255,255,.10);
+  border-radius:14px;
+  overflow:hidden;
+  background: rgba(18,32,51,.45);
+}
+.acc button{
+  width:100%;
+  padding:14px 14px;
+  display:flex;align-items:center;justify-content:space-between;
+  gap:10px;
+  background: transparent;
+  border:0;
+  color:var(--text);
+  font-weight:700;
+  cursor:pointer;
+}
+.acc button span{color:var(--muted);font-weight:600}
+.acc .panel{padding:0 14px 14px;color:var(--muted);display:none}
+.acc[data-open="true"] .panel{display:block}
+.chev{width:18px;height:18px;opacity:.8;transition: transform .15s ease}
