+.carousel{margin-top:18px}
+.track{
+  display:flex;gap:16px;
+  transition: transform .35s ease;
+  will-change: transform;
+}
+.slide{min-width:100%}
+.testimonial{
+  border:1px solid rgba(255,255,255,.10);
+  border-radius:var(--radius);
+  padding:18px;
+  background: rgba(18,32,51,.55);
+}
