+.dotbtn[aria-current="true"]{background: rgba(0,180,216,.60);border-color: rgba(0,180,216,.70)}
+
+/* Forms */
+form{margin-top:16px}
+.form-grid{display:grid;grid-template-columns:repeat(2, 1fr);gap:12px}
+.field{display:flex;flex-direction:column;gap:6px}
+.field label{font-size:12px;color:var(--muted)}
+.field input,.field select,.field textarea{
+  border-radius:12px;
+  border:1px solid rgba(255,255,255,.12);
+  background: rgba(255,255,255,.03);
+  color: var(--text);
+  padding:10px 12px;
+  outline:none;
+}
+.field textarea{min-height:110px;resize:vertical}
+.field input:focus,.field select:focus,.field textarea:focus{border-color: rgba(0,180,216,.45);box-shadow: 0 0 0 3px rgba(0,180,216,.12)}
+.error{color:#ffb4b4;font-size:12px;display:none}
+.field[data-error="true"] .error{display:block}
+.field[data-error="true"] input,.field[data-error="true"] select,.field[data-error="true"] textarea{border-color: rgba(255,120,120,.55)}
+.form-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:12px}
+.fine{color:var(--muted);font-size:12px;max-width:520px}
+.success{
+  margin-top:12px;
+  padding:12px 14px;
+  border-radius:12px;
+  border:1px solid rgba(108,194,74,.25);
+  background: rgba(108,194,74,.10);
+  color: rgba(215,255,226,.95);
+  display:none;
+}
+.success.show{display:block}
+
+/* Footer */
+footer{border-top:1px solid rgba(255,255,255,.08);background: rgba(9,18,30,.65)}
+.footer{padding:38px 0}
+.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:18px}
+.footer h4{margin:0 0 10px;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:rgba(231,238,248,.85)}
+.footer a{display:block;padding:6px 0;color:var(--muted);font-size:14px}
+.footer a:hover{color:var(--text)}
+.legal{margin-top:18px;color:var(--muted);font-size:12px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
+
+/* Cookie banner */
+.cookie{
+  position:fixed;left:18px;right:18px;bottom:18px;z-index:60;
+  max-width: 980px;margin:0 auto;
+  border-radius: 16px;
+  border:1px solid rgba(255,255,255,.12);
+  background: rgba(18,32,51,.92);
+  box-shadow: var(--shadow);
+  padding:14px;
+  display:none;
+}
+.cookie.show{display:block}
+.cookie .row{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;flex-wrap:wrap}
+.cookie p{margin:0;color:var(--muted);font-size:13px;max-width:680px}
+.cookie .actions{display:flex;gap:10px}
+
+/* Page-specific small helpers */
+.callout{
+  background: radial-gradient(600px 260px at 20% 10%, rgba(0,180,216,.16), transparent 60%),
+              rgba(18,32,51,.55);
+  border:1px solid rgba(0,180,216,.18);
+  border-radius:var(--radius);
+  padding:18px;
+}
+.checklist{display:grid;gap:10px;margin-top:14px}
+.check{
+  display:flex;gap:10px;align-items:flex-start;
+  padding:10px 12px;border-radius:14px;
+  border:1px solid rgba(255,255,255,.10);
+  background: rgba(255,255,255,.03);
+}
+.check svg{width:16px;height:16px;flex:0 0 auto;margin-top:2px;color:var(--good)}
+.check strong{display:block;margin-bottom:2px}
+.check span{color:var(--muted);font-size:13px}
+
+.split{display:grid;grid-template-columns: 1fr 1fr;gap:16px;align-items:start}
+
+/* Responsive */
+@media (max-width: 980px){
+  .grid.two{grid-template-columns:1fr}
+  .grid.cards{grid-template-columns:repeat(2, 1fr)}
+  .footer-grid{grid-template-columns:1fr 1fr}
+  .stats{grid-template-columns:1fr}
+}
+
+@media (max-width: 720px){
+  .hero h1{font-size:34px}
+  .nav-links{display:none}
+  .mobile-toggle{display:inline-flex}
+  .mobile-panel{
+    display:none;
+    border-top:1px solid rgba(255,255,255,.08);
+    padding:12px 0 14px;
+  }
+  .mobile-panel.open{display:block}
+  .mobile-panel a{display:block;padding:10px 0;color:var(--muted)}
+  .mobile-panel a:hover{color:var(--text)}
+  .grid.cards{grid-template-columns:1fr}
+  .form-grid{grid-template-columns:1fr}
+  .split{grid-template-columns:1fr}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{transition:none !important;scroll-behavior:auto !important}
+}
+
*** End Patch
PATCH

